export const BANK = [
/* ================= SOFTWARE ================= */
{d:"sw",t:"SDLC & methods",q:"Requirements are fixed, well understood and unlikely to change, and the client wants each phase signed off before the next begins. Which process model fits best?",o:["Waterfall","Scrum","Spiral","Extreme Programming"],a:0,e:"Waterfall runs phases in strict sequence with sign-off between them. It suits stable, well-understood requirements; Agile methods are chosen when requirements are expected to change."},
{d:"sw",t:"SDLC & methods",q:"In Scrum, who is responsible for ordering (prioritizing) the Product Backlog?",o:["Scrum Master","Product Owner","Development team lead","Project sponsor"],a:1,e:"The Product Owner owns and orders the Product Backlog to maximize value. The Scrum Master coaches the process and removes impediments."},
{d:"sw",t:"SDLC & methods",q:"Which Scrum event is held to inspect how the last Sprint went with regard to people, processes and tools, and to plan improvements?",o:["Sprint Review","Daily Scrum","Sprint Retrospective","Sprint Planning"],a:2,e:"The Retrospective looks at how the team worked. The Sprint Review inspects the product increment with stakeholders."},
{d:"sw",t:"SDLC & methods",q:"Which process model places explicit risk analysis at the center of every iteration?",o:["V-model","Spiral model","Waterfall","Big bang"],a:1,e:"Boehm's Spiral model cycles through planning, risk analysis, engineering and evaluation, making it suited to large, high-risk projects."},
{d:"sw",t:"SDLC & methods",q:"In the V-model, acceptance testing is planned and verified against which development phase?",o:["Detailed design","Coding","Requirements analysis","Architectural design"],a:2,e:"Each left-side phase pairs with a test level: requirements with acceptance testing, architecture with integration/system testing, detailed design with unit testing."},
{d:"sw",t:"SDLC & methods",q:"Which statement is one of the four values of the Agile Manifesto?",o:["Processes and tools over individuals and interactions","Comprehensive documentation over working software","Responding to change over following a plan","Contract negotiation over customer collaboration"],a:2,e:"The values favor individuals and interactions, working software, customer collaboration, and responding to change. The other options reverse them."},
{d:"sw",t:"SDLC & methods",q:"A team merges code to the shared main branch several times a day, and each merge triggers an automated build and test run. This practice is called:",o:["Continuous Integration","Pair programming","Code freeze","Waterfall integration"],a:0,e:"Continuous Integration catches integration problems early through frequent merges with automated build and test. Continuous Delivery/Deployment extends it to releases."},
{d:"sw",t:"Requirements",q:"Which of the following is a non-functional requirement?",o:["The system shall let users reset their password by email","The system shall respond to 95% of search requests within 2 seconds","The system shall calculate the monthly water bill from meter readings","The system shall allow admins to deactivate accounts"],a:1,e:"Non-functional requirements describe quality attributes such as performance, security and usability. The others describe functions the system performs."},
{d:"sw",t:"Requirements",q:"What is the main purpose of a requirements traceability matrix?",o:["To estimate project cost","To link each requirement to its design, code and test cases","To record defects found in testing","To assign developers to modules"],a:1,e:"Traceability lets you confirm every requirement is implemented and tested, and see what is affected when a requirement changes."},
{d:"sw",t:"Requirements",q:"Which requirement statement is the most verifiable (testable)?",o:["The interface shall be user-friendly","The system shall be fast","The report page shall load in under 3 seconds with 500 concurrent users","The system shall be highly secure"],a:2,e:"A good requirement is measurable. Terms like user-friendly, fast and secure cannot be tested without a measurable criterion."},
{d:"sw",t:"UML & design",q:"In a use case diagram, what does an <<include>> relationship from use case A to use case B mean?",o:["B optionally extends A under some condition","A always incorporates the behavior of B","B is a subtype of A","A and B are performed by different actors"],a:1,e:"<<include>> means the base use case always uses the included one (e.g. Checkout includes Authenticate). <<extend>> is for optional or conditional behavior."},
{d:"sw",t:"UML & design",q:"In a UML class diagram, a filled (black) diamond on the House end of a House-Room association indicates:",o:["Aggregation: rooms can exist without the house","Composition: rooms cannot exist without the house","Inheritance: Room is a kind of House","Dependency: House uses Room temporarily"],a:1,e:"Composition (filled diamond) is a strong whole-part relationship where parts share the lifetime of the whole. Aggregation uses a hollow diamond."},
{d:"sw",t:"UML & design",q:"Which UML diagram best shows the messages exchanged between objects in time order for one scenario?",o:["Class diagram","Sequence diagram","Deployment diagram","Component diagram"],a:1,e:"Sequence diagrams arrange lifelines horizontally and messages vertically in time order."},
{d:"sw",t:"UML & design",q:"You need to model how an Order moves through Created, Paid, Shipped, Delivered and Cancelled in response to events. Which diagram fits best?",o:["Activity diagram","State machine diagram","Use case diagram","Object diagram"],a:1,e:"State machine diagrams model the states of one object and the events/transitions between them."},
{d:"sw",t:"UML & design",q:"Which combination indicates good modular design?",o:["High coupling, high cohesion","Low coupling, low cohesion","Low coupling, high cohesion","High coupling, low cohesion"],a:2,e:"Modules should be focused on one job (high cohesion) and depend on each other as little as possible (low coupling)."},
{d:"sw",t:"UML & design",q:"Which type of coupling is the loosest (most desirable)?",o:["Content coupling","Common coupling","Control coupling","Data coupling"],a:3,e:"From loosest to tightest: data, stamp, control, external, common, content. Data coupling passes only the needed elementary data through parameters."},
{d:"sw",t:"UML & design",q:"Which type of cohesion is considered the strongest?",o:["Coincidental","Logical","Temporal","Functional"],a:3,e:"Functional cohesion means every element of the module contributes to a single well-defined task. Coincidental is the weakest."},
{d:"sw",t:"UML & design",q:"In the MVC pattern, which component receives user input and decides how the model and view should respond?",o:["Model","View","Controller","Repository"],a:2,e:"The Controller handles input, updates the Model, and selects the View. The Model holds data and business rules; the View renders it."},
{d:"sw",t:"UML & design",q:"Which is a key advantage of a microservices architecture over a monolith?",o:["Simpler distributed transactions","Each service can be deployed and scaled independently","Lower network overhead","A single shared database for all services"],a:1,e:"Independent deployment and scaling is the main benefit. The trade-offs are network overhead and harder distributed data consistency."},
{d:"sw",t:"Design patterns",q:"Which design pattern ensures a class has only one instance and provides a global access point to it?",o:["Factory Method","Singleton","Prototype","Builder"],a:1,e:"Singleton restricts instantiation to one object, e.g. a configuration manager or connection pool."},
{d:"sw",t:"Design patterns",q:"When a weather station's reading changes, all registered displays must update automatically. Which pattern fits?",o:["Observer","Adapter","Decorator","Facade"],a:0,e:"Observer defines a one-to-many dependency so dependents (subscribers) are notified when the subject changes."},
{d:"sw",t:"Design patterns",q:"A payment module must switch between card, e-wallet and bank-transfer algorithms at runtime without changing client code. Which pattern fits?",o:["Strategy","Singleton","Composite","Template Method"],a:0,e:"Strategy encapsulates interchangeable algorithms behind a common interface so they can be swapped at runtime."},
{d:"sw",t:"Design patterns",q:"You must use a legacy library whose interface does not match the one your code expects, without modifying the library. Which pattern converts one interface into another?",o:["Proxy","Adapter","Observer","Mediator"],a:1,e:"Adapter wraps an existing class to make it compatible with the interface clients expect."},
{d:"sw",t:"Design patterns",q:"Design patterns are grouped as creational, structural and behavioral. Which is a creational pattern?",o:["Factory Method","Decorator","Iterator","Observer"],a:0,e:"Creational: Singleton, Factory Method, Abstract Factory, Builder, Prototype. Decorator is structural; Iterator and Observer are behavioral."},
{d:"sw",t:"Design patterns",q:"\"Software entities should be open for extension but closed for modification.\" Which SOLID principle is this?",o:["Single Responsibility","Open/Closed","Liskov Substitution","Dependency Inversion"],a:1,e:"The Open/Closed Principle: add new behavior by extending (e.g. new subclasses or strategies) rather than editing working code."},
{d:"sw",t:"Testing",q:"An input field accepts integers from 1 to 100. Using boundary value analysis, which set of test values is most appropriate?",o:["1, 50, 100","0, 1, 100, 101","-1, 50, 200","10, 20, 30, 40"],a:1,e:"Boundary value analysis tests just inside and just outside each boundary: 0 and 1 at the lower edge, 100 and 101 at the upper edge."},
{d:"sw",t:"Testing",q:"Black-box testing techniques include all of the following EXCEPT:",o:["Equivalence partitioning","Boundary value analysis","Decision table testing","Branch coverage"],a:3,e:"Branch (decision) coverage needs knowledge of the code's structure, so it is a white-box technique."},
{d:"sw",t:"Testing",q:"In top-down integration testing, lower-level modules that are not yet implemented are replaced by:",o:["Drivers","Stubs","Mocks of the UI","Test oracles"],a:1,e:"Top-down uses stubs to stand in for called lower modules. Bottom-up uses drivers to call the modules under test."},
{d:"sw",t:"Testing",q:"After fixing a bug, the team re-runs previously passing tests to make sure nothing else broke. This is:",o:["Smoke testing","Regression testing","Acceptance testing","Load testing"],a:1,e:"Regression testing checks that changes have not broken existing functionality."},
{d:"sw",t:"Testing",q:"What is the cyclomatic complexity V(G) of this function?",c:`def grade(score, bonus):
    if bonus:
        score += 5
    if score >= 90:
        g = "A"
    elif score >= 75:
        g = "B"
    else:
        g = "C"
    while score > 100:
        score -= 1
    return g`,o:["3","4","5","6"],a:2,k:"code",e:"V(G) = number of decision points + 1. Decisions: if bonus, if score >= 90, elif score >= 75, while. That is 4 + 1 = 5."},
{d:"sw",t:"Testing",q:"For the code below, what is the minimum number of test cases needed for 100% branch (decision) coverage?",c:`if (age >= 18) {
    status = "adult";
} else {
    status = "minor";
}
if (member) {
    discount = 0.1;
}`,o:["1","2","3","4"],a:1,k:"code",e:"Two tests suffice: (age >= 18, member = true) covers both true branches; (age < 18, member = false) covers both false branches."},
{d:"sw",t:"Testing",q:"Which test level is usually performed by end users or the client to decide whether to accept the system?",o:["Unit testing","Integration testing","System testing","Acceptance testing"],a:3,e:"Acceptance testing (e.g. UAT) validates the system against business needs from the customer's perspective."},
{d:"sw",t:"Testing",q:"Restructuring code to improve readability and maintainability without changing its external behavior is called:",o:["Reverse engineering","Refactoring","Re-engineering the requirements","Debugging"],a:1,e:"Refactoring keeps observable behavior the same; a good test suite is what makes it safe."},
{d:"sw",t:"Algorithms & DS",q:"Binary search on an array of n elements has what time complexity, and what does it require?",o:["O(n), unsorted array","O(log n), sorted array","O(n log n), sorted array","O(1), hashed array"],a:1,e:"Binary search halves the search space each step, giving O(log n), but only works on sorted data."},
{d:"sw",t:"Algorithms & DS",q:"Starting from an empty stack: push 1, push 2, push 3, pop, push 4, pop, pop. What values are popped, in order?",o:["3, 4, 2","1, 2, 4","3, 2, 4","3, 4, 1"],a:0,e:"After pushes the stack is [1,2,3]; pop gives 3. Push 4 gives [1,2,4]; pop gives 4; pop gives 2. A stack is LIFO."},
{d:"sw",t:"Algorithms & DS",q:"Starting from an empty queue: enqueue 5, enqueue 8, enqueue 2, dequeue, enqueue 7, dequeue. What is now at the front?",o:["5","8","2","7"],a:2,e:"Queue is FIFO: [5,8,2] then dequeue 5 gives [8,2], enqueue 7 gives [8,2,7], dequeue 8 gives [2,7]. Front is 2."},
{d:"sw",t:"Algorithms & DS",q:"Which sorting algorithm guarantees O(n log n) time in the worst case?",o:["Quick sort","Insertion sort","Merge sort","Bubble sort"],a:2,e:"Merge sort is O(n log n) in all cases. Quick sort degrades to O(n^2) with bad pivots; insertion and bubble are O(n^2) worst case."},
{d:"sw",t:"Algorithms & DS",q:"Breadth-first search (BFS) of a graph is normally implemented with which data structure?",o:["Stack","Queue","Heap","Binary search tree"],a:1,e:"BFS visits nodes level by level using a FIFO queue. DFS uses a stack (or recursion)."},
{d:"sw",t:"Algorithms & DS",q:"Storing all keys that hash to the same slot in a linked list at that slot is which collision-resolution method?",o:["Linear probing","Separate chaining","Double hashing","Rehashing"],a:1,e:"Separate chaining keeps a list per bucket. Linear probing and double hashing are open-addressing methods."},
{d:"sw",t:"Algorithms & DS",q:"What is the time complexity of this code?",c:`for i in range(n):
    for j in range(i, n):
        count += 1`,o:["O(n)","O(n log n)","O(n^2)","O(2^n)"],a:2,k:"code",e:"The inner loop runs n + (n-1) + ... + 1 = n(n+1)/2 times, which is O(n^2)."},
{d:"sw",t:"Code tracing",q:"What does this Python code print?",c:`total = 0
for i in range(1, 10, 3):
    total += i
print(total)`,o:["12","15","22","45"],a:0,k:"code",e:"range(1, 10, 3) produces 1, 4, 7. Their sum is 12."},
{d:"sw",t:"Code tracing",q:"What does this Python code print?",c:`def f(n):
    if n <= 1:
        return 1
    return n * f(n - 2)

print(f(7))`,o:["105","5040","48","35"],a:0,k:"code",e:"f(7) = 7 * f(5) = 7 * 5 * f(3) = 7 * 5 * 3 * f(1) = 105."},
{d:"sw",t:"Code tracing",q:"What does this Java code print?",c:`int x = 17;
int y = 5;
System.out.println(x / y + x % y);`,o:["3","5","5.4","6"],a:1,k:"code",e:"Integer division 17 / 5 = 3, and 17 % 5 = 2. 3 + 2 = 5."},
{d:"sw",t:"Code tracing",q:"What does this Python code print?",c:`a = [3, 1, 4, 1, 5]
for i in range(len(a) - 1):
    if a[i] > a[i + 1]:
        a[i], a[i + 1] = a[i + 1], a[i]
print(a)`,o:["[1, 1, 3, 4, 5]","[1, 3, 1, 4, 5]","[1, 3, 4, 1, 5]","[3, 1, 4, 1, 5]"],a:1,k:"code",e:"This is one bubble-sort pass. Swap 3 and 1 gives [1,3,4,1,5]; 3 and 4 stay; swap 4 and 1 gives [1,3,1,4,5]; 4 and 5 stay."},
{d:"sw",t:"Code tracing",q:"What does this C code print?",c:`int count = 0;
for (int i = 0; i < 5; i++)
    for (int j = i; j < 5; j++)
        count++;
printf("%d", count);`,o:["10","15","20","25"],a:1,k:"code",e:"Inner loop runs 5, 4, 3, 2, 1 times. 5 + 4 + 3 + 2 + 1 = 15."},
{d:"sw",t:"Code tracing",q:"What does this Java code print?",c:`class Animal { String sound() { return "..."; } }
class Dog extends Animal {
    @Override String sound() { return "Woof"; }
}

Animal a = new Dog();
System.out.println(a.sound());`,o:["...","Woof","Compile error","Runtime error"],a:1,k:"code",e:"Dynamic dispatch (runtime polymorphism) calls the overriding method of the actual object type, Dog."},
{d:"sw",t:"Code tracing",q:"What does this Python code print?",c:`s = "TOPCIT"
print(s[1:4] + s[-1])`,o:["TOPT","OPCT","OPCI","OPT"],a:1,k:"code",e:"s[1:4] takes indexes 1 to 3: \"OPC\". s[-1] is the last character \"T\". Result: \"OPCT\"."},
{d:"sw",t:"Code tracing",q:"What does this Python code print?",c:`a = [1, 2, 3]
b = a
b.append(4)
print(len(a))`,o:["3","4","Error","None"],a:1,k:"code",e:"b = a copies the reference, not the list. Both names point to the same list, so a also has 4 elements."},
{d:"sw",t:"Code tracing",q:"What does this Python code print?",c:`x = 0
if x != 0 and 10 / x > 1:
    print("A")
else:
    print("B")`,o:["A","B","ZeroDivisionError","Nothing"],a:1,k:"code",e:"Short-circuit evaluation: x != 0 is False, so 10 / x is never evaluated. The else branch prints B."},

/* ================= DATA ================= */
{d:"db",t:"ER modeling",q:"A student can enroll in many courses and a course has many students. How is this relationship implemented in a relational schema?",o:["Put CourseID as a foreign key in Student","Put StudentID as a foreign key in Course","Create an associative (junction) table Enrollment with both keys","Merge Student and Course into one table"],a:2,e:"An M:N relationship is resolved with a junction table whose primary key is usually the combination of both foreign keys."},
{d:"db",t:"ER modeling",q:"An entity that cannot be uniquely identified by its own attributes and depends on an owner entity is a:",o:["Strong entity","Weak entity","Associative entity","Supertype"],a:1,e:"A weak entity (e.g. Dependent of Employee) is identified by its partial key plus the owner's key."},
{d:"db",t:"ER modeling",q:"A minimal superkey (no attribute can be removed and it is still unique) is called a:",o:["Foreign key","Candidate key","Composite attribute","Surrogate key"],a:1,e:"Every candidate key is a minimal superkey. One candidate key is chosen as the primary key."},
{d:"db",t:"ER modeling",q:"Referential integrity requires that a foreign key value:",o:["Is always unique","Is never NULL","Matches an existing primary key value in the referenced table, or is NULL","Is the same as the table's primary key"],a:2,e:"A foreign key must reference an existing row (or be NULL if allowed). Entity integrity is the rule that a primary key cannot be NULL."},
{d:"db",t:"ER modeling",q:"A database view is best described as:",o:["A physical copy of a table","A virtual table defined by a stored query","An index on several columns","A backup snapshot"],a:1,e:"A view stores a query, not data (unless materialized). It is used for security and to simplify complex queries."},
{d:"db",t:"Normalization",q:"A table is in First Normal Form (1NF) when:",o:["It has no transitive dependencies","All attribute values are atomic, with no repeating groups","Every determinant is a candidate key","It has no partial dependencies"],a:1,e:"1NF requires atomic values in each cell and no repeating groups."},
{d:"db",t:"Normalization",q:"Enrollment(StudentID, CourseID, StudentName, Grade) has primary key (StudentID, CourseID). StudentName depends only on StudentID. Which normal form is violated?",o:["1NF","2NF","3NF","None"],a:1,e:"StudentName depends on part of the composite key, which is a partial dependency. Removing partial dependencies is the step to 2NF."},
{d:"db",t:"Normalization",q:"Employee(EmpID, Name, DeptID, DeptName) has primary key EmpID. DeptName depends on DeptID. Which normal form is violated?",o:["1NF","2NF","3NF","It is fully normalized"],a:2,e:"EmpID determines DeptID, which determines DeptName. That transitive dependency violates 3NF. Fix: move DeptName to Department(DeptID, DeptName)."},
{d:"db",t:"Normalization",q:"A relation is in Boyce-Codd Normal Form (BCNF) when:",o:["Every determinant is a candidate key","It has no multivalued attributes","It has a single-column primary key","All non-key attributes are NULL-free"],a:0,e:"BCNF is a stricter 3NF: for every functional dependency X -> Y, X must be a candidate key (superkey)."},
{d:"db",t:"Normalization",q:"A customer's address is stored in 300 order rows. Changing it in only some rows leaves inconsistent data. This is a(n):",o:["Insertion anomaly","Deletion anomaly","Update anomaly","Phantom read"],a:2,e:"Update anomalies come from redundancy: the same fact stored in many places must be changed everywhere."},
{d:"db",t:"Normalization",q:"Why would a designer intentionally denormalize part of a schema?",o:["To reduce storage space","To improve read/query performance at the cost of redundancy","To enforce referential integrity","To eliminate update anomalies"],a:1,e:"Denormalization reduces joins for read-heavy workloads (e.g. reporting) but reintroduces redundancy that must be managed."},
{d:"db",t:"SQL",q:"Which query lists departments that have more than 5 employees?",o:["SELECT dept_id, COUNT(*) FROM emp WHERE COUNT(*) > 5 GROUP BY dept_id;","SELECT dept_id, COUNT(*) FROM emp GROUP BY dept_id HAVING COUNT(*) > 5;","SELECT dept_id FROM emp HAVING COUNT(*) > 5;","SELECT dept_id, COUNT(*) FROM emp ORDER BY COUNT(*) > 5;"],a:1,e:"Aggregate conditions go in HAVING, after GROUP BY. WHERE filters rows before grouping and cannot use aggregates."},
{d:"db",t:"SQL",q:"What does a LEFT OUTER JOIN return?",o:["Only rows with matches in both tables","All rows from the left table, with NULLs where the right table has no match","All rows from the right table only","Every combination of rows from both tables"],a:1,e:"LEFT JOIN keeps every left-table row. Unmatched rows get NULL for right-table columns."},
{d:"db",t:"SQL",q:"Table A has 3 rows and table B has 4 rows. How many rows does SELECT * FROM A CROSS JOIN B return?",o:["7","4","12","3"],a:2,e:"A cross join is a Cartesian product: 3 x 4 = 12 rows."},
{d:"db",t:"SQL",q:"Which statement removes a table's data AND its definition (structure) from the database?",o:["DELETE FROM t;","TRUNCATE TABLE t;","DROP TABLE t;","UPDATE t SET * = NULL;"],a:2,e:"DROP removes the table itself. TRUNCATE removes all rows but keeps the structure. DELETE removes rows (optionally filtered) and is DML."},
{d:"db",t:"SQL",q:"A query uses WHERE commission = NULL and returns no rows, although some commissions are NULL. What is the fix?",o:["WHERE commission == NULL","WHERE commission IS NULL","WHERE commission = 'NULL'","WHERE ISNULL = commission"],a:1,e:"Any comparison with NULL using = yields UNKNOWN, not TRUE. Use IS NULL or IS NOT NULL."},
{d:"db",t:"SQL",q:"Table Scores has rows (A, 80), (B, NULL), (C, 60). What does this return?",c:`SELECT COUNT(*), COUNT(score), AVG(score)
FROM Scores;`,o:["3, 3, 46.67","3, 2, 70","2, 2, 70","3, 2, 46.67"],a:1,k:"code",e:"COUNT(*) counts rows (3). COUNT(score) and AVG ignore NULLs: 2 values, average (80 + 60) / 2 = 70."},
{d:"db",t:"SQL",q:"How many rows does this query return?",c:`Employee
id | name | dept | salary
1  | Ana  | IT   | 50
2  | Ben  | IT   | 70
3  | Cara | HR   | 40
4  | Dan  | HR   | 60
5  | Eve  | OPS  | 55

SELECT dept, AVG(salary)
FROM Employee
GROUP BY dept
HAVING AVG(salary) > 50;`,o:["1","2","3","5"],a:1,k:"code",e:"Averages: IT = 60, HR = 50, OPS = 55. HR is not greater than 50, so IT and OPS remain: 2 rows."},
{d:"db",t:"SQL",q:"Students has S1, S2, S3, S4. Enrollment has (S1, C1), (S1, C2), (S2, C1). How many rows does this return?",c:`SELECT *
FROM Students s
LEFT JOIN Enrollment e ON s.id = e.sid;`,o:["3","4","5","6"],a:2,k:"code",e:"S1 matches twice (2 rows), S2 once (1 row), S3 and S4 have no match but are kept with NULLs (2 rows). Total 5."},
{d:"db",t:"SQL",q:"Which query returns employees who earn more than the company average salary?",o:["SELECT * FROM emp WHERE salary > AVG(salary);","SELECT * FROM emp HAVING salary > AVG(salary);","SELECT * FROM emp WHERE salary > (SELECT AVG(salary) FROM emp);","SELECT * FROM emp GROUP BY salary > AVG(salary);"],a:2,e:"Aggregates cannot appear directly in WHERE. A scalar subquery computes the average first."},
{d:"db",t:"SQL",q:"GRANT and REVOKE belong to which category of SQL?",o:["DDL","DML","DCL","TCL"],a:2,e:"DCL (Data Control Language) manages privileges. DDL: CREATE/ALTER/DROP. DML: SELECT/INSERT/UPDATE/DELETE. TCL: COMMIT/ROLLBACK/SAVEPOINT."},
{d:"db",t:"SQL",q:"What is the difference between UNION and UNION ALL?",o:["UNION ALL removes duplicates; UNION keeps them","UNION removes duplicate rows; UNION ALL keeps all rows","UNION requires the same table; UNION ALL does not","There is no difference"],a:1,e:"UNION performs duplicate elimination (extra sort/hash cost). UNION ALL simply appends results."},
{d:"db",t:"SQL",q:"Why does SELECT price * qty AS total FROM sales WHERE total > 100 fail in standard SQL?",o:["Aliases are not allowed for expressions","WHERE is logically processed before SELECT, so the alias does not exist yet","Multiplication is not allowed in SELECT","WHERE must come after ORDER BY"],a:1,e:"Logical order: FROM, WHERE, GROUP BY, HAVING, SELECT, ORDER BY. Repeat the expression in WHERE or use a subquery. ORDER BY can use the alias."},
{d:"db",t:"Transactions",q:"In ACID, which property guarantees that once a transaction commits, its changes survive a system crash?",o:["Atomicity","Consistency","Isolation","Durability"],a:3,e:"Durability is typically ensured with write-ahead logs. Atomicity is all-or-nothing; Isolation hides concurrent transactions from each other."},
{d:"db",t:"Transactions",q:"A bank transfer debits account A but crashes before crediting account B. Which ACID property requires the debit to be rolled back?",o:["Atomicity","Consistency","Isolation","Durability"],a:0,e:"Atomicity: a transaction is all or nothing. Partial work is undone on failure."},
{d:"db",t:"Transactions",q:"Transaction T1 reads a value that T2 has updated but not yet committed; T2 then rolls back. What problem occurred?",o:["Lost update","Dirty read","Phantom read","Deadlock"],a:1,e:"Reading uncommitted data is a dirty read. READ COMMITTED and higher isolation levels prevent it."},
{d:"db",t:"Transactions",q:"Which isolation level prevents dirty reads but still allows non-repeatable reads?",o:["READ UNCOMMITTED","READ COMMITTED","REPEATABLE READ","SERIALIZABLE"],a:1,e:"READ COMMITTED blocks dirty reads only. REPEATABLE READ also blocks non-repeatable reads; SERIALIZABLE also blocks phantoms."},
{d:"db",t:"Transactions",q:"Two-phase locking (2PL) is used to guarantee:",o:["Deadlock freedom","Conflict serializability","Faster reads","Automatic backups"],a:1,e:"2PL (growing phase then shrinking phase) guarantees conflict-serializable schedules, but it can still cause deadlocks."},
{d:"db",t:"Transactions",q:"T1 holds a lock on row X and waits for row Y; T2 holds a lock on row Y and waits for row X. This is a:",o:["Livelock","Deadlock","Dirty read","Cascading rollback"],a:1,e:"Circular waiting on locks is a deadlock. DBMSs detect it and abort one transaction as the victim."},
{d:"db",t:"Indexing & storage",q:"Which index structure supports both equality and range queries (e.g. BETWEEN) efficiently?",o:["Hash index","B+ tree index","Bitmap of primary keys","No index"],a:1,e:"B+ trees keep keys sorted with linked leaves, so ranges are efficient. Hash indexes only support equality lookups well."},
{d:"db",t:"Indexing & storage",q:"What is a main drawback of adding many indexes to a table?",o:["SELECT queries become slower","INSERT, UPDATE and DELETE become slower and storage grows","Primary keys are no longer unique","Joins are no longer possible"],a:1,e:"Every index must be maintained on writes. Index columns used often in WHERE/JOIN, not everything."},
{d:"db",t:"Indexing & storage",q:"Which statement about a clustered index is true?",o:["A table can have many clustered indexes","It determines the physical order of the table's rows, so there is only one per table","It cannot be built on a primary key","It is stored separately from the data with pointers only"],a:1,e:"Rows are physically ordered by the clustered key, so only one is possible. Non-clustered indexes are separate structures with pointers."},
{d:"db",t:"Big data & DW",q:"A star schema consists of:",o:["One central fact table linked to several dimension tables","Several fact tables with no dimensions","Fully normalized tables only","A single denormalized table"],a:0,e:"Fact tables hold measures (sales amount, qty); dimension tables hold descriptive context (date, product, store). Used in data warehouses for OLAP."},
{d:"db",t:"Big data & DW",q:"Which workload description fits OLAP rather than OLTP?",o:["Many short insert/update transactions from cashiers","Complex aggregate queries over historical data for analysis","Real-time ticket booking","Updating one customer's address"],a:1,e:"OLTP handles day-to-day transactions; OLAP supports analysis over large historical data, often in a warehouse."},
{d:"db",t:"Big data & DW",q:"In ETL, what does the T stage do?",o:["Transmits data to users","Transforms (cleans, converts, aggregates) data before loading","Tests the warehouse","Truncates old tables"],a:1,e:"Extract from sources, Transform (clean, standardize, join, aggregate), Load into the target such as a data warehouse."},
{d:"db",t:"Big data & DW",q:"The classic 3 Vs of big data are:",o:["Volume, Velocity, Variety","Value, Validity, Visibility","Volume, Version, Vendor","Velocity, Virtualization, Verification"],a:0,e:"Volume (size), Velocity (speed of generation), Variety (structured, semi-structured, unstructured). Veracity and Value are often added."},
{d:"db",t:"Big data & DW",q:"According to the CAP theorem, when a network partition occurs a distributed database must choose between:",o:["Cost and performance","Consistency and availability","Atomicity and durability","Indexing and caching"],a:1,e:"Partition tolerance is unavoidable in distributed systems, so during a partition the system must sacrifice either consistency or availability."},
{d:"db",t:"Big data & DW",q:"Which type of NoSQL database stores data as JSON-like documents (e.g. MongoDB)?",o:["Key-value store","Document store","Column-family store","Graph database"],a:1,e:"Document stores hold semi-structured documents. Redis is key-value, Cassandra is column-family, Neo4j is a graph database."},

/* ================= SYSTEMS & SECURITY ================= */
{d:"sa",t:"Operating systems",q:"Which statement correctly contrasts processes and threads?",o:["Threads of the same process share its memory address space","Each thread has its own separate address space","Processes share all memory by default","Threads cannot run concurrently"],a:0,e:"Threads share code, data and heap of their process (each has its own stack and registers), so they are lighter but need synchronization."},
{d:"sa",t:"Operating systems",q:"P1 (burst 24), P2 (burst 3), P3 (burst 3) all arrive at time 0 in that order. Using FCFS, what is the average waiting time?",o:["3","13","17","27"],a:2,e:"Waiting times: P1 = 0, P2 = 24, P3 = 27. Average = 51 / 3 = 17. Running the short jobs first (SJF) would give (0 + 3 + 6) / 3 = 3."},
{d:"sa",t:"Operating systems",q:"Which CPU scheduling algorithm minimizes average waiting time when burst lengths are known?",o:["First-Come, First-Served","Shortest Job First","Round Robin","Priority with aging"],a:1,e:"SJF is provably optimal for average waiting time, but it can starve long jobs and requires knowing burst lengths."},
{d:"sa",t:"Operating systems",q:"Which is NOT one of the four necessary conditions for deadlock?",o:["Mutual exclusion","Hold and wait","Starvation","Circular wait"],a:2,e:"The Coffman conditions are mutual exclusion, hold and wait, no preemption, and circular wait. Starvation is a different problem."},
{d:"sa",t:"Operating systems",q:"A page fault occurs when:",o:["A process accesses a page that is not currently in physical memory","The CPU cache is full","Two processes write to the same file","The disk runs out of space"],a:0,e:"The OS must then load the page from secondary storage, possibly evicting another page with a replacement algorithm such as LRU."},
{d:"sa",t:"Operating systems",q:"Which page replacement algorithm can suffer from Belady's anomaly (more frames causing more faults)?",o:["LRU","Optimal","FIFO","LFU with aging"],a:2,e:"FIFO can show Belady's anomaly. Stack algorithms like LRU and Optimal cannot."},
{d:"sa",t:"Operating systems",q:"Which mechanism is commonly used to ensure only one thread enters a critical section at a time?",o:["Mutex (or binary semaphore)","Page table","Interrupt vector","Spooler"],a:0,e:"A mutex or semaphore provides mutual exclusion around shared data to prevent race conditions."},
{d:"sa",t:"Networking",q:"At which OSI layer do routers forward packets based on IP addresses?",o:["Data link (Layer 2)","Network (Layer 3)","Transport (Layer 4)","Session (Layer 5)"],a:1,e:"Routing by logical (IP) address is Layer 3. Switches forward by MAC address at Layer 2."},
{d:"sa",t:"Networking",q:"Which correctly describes TCP compared to UDP?",o:["TCP is connectionless and faster","TCP is connection-oriented and provides reliable, ordered delivery","TCP has no flow control","TCP is used for all DNS queries and live video"],a:1,e:"TCP uses handshakes, acknowledgements, retransmission and flow control. UDP is connectionless and lighter, used for DNS queries, VoIP and streaming."},
{d:"sa",t:"Networking",q:"What is the order of the TCP three-way handshake?",o:["SYN, ACK, FIN","SYN, SYN-ACK, ACK","ACK, SYN, SYN-ACK","SYN, FIN, ACK"],a:1,e:"Client sends SYN, server replies SYN-ACK, client sends ACK. Connection teardown uses FIN."},
{d:"sa",t:"Networking",q:"How many usable host addresses does a /26 subnet provide?",o:["30","62","64","126"],a:1,e:"/26 leaves 6 host bits: 2^6 = 64 addresses, minus network and broadcast = 62 usable."},
{d:"sa",t:"Networking",q:"What is the network address of host 192.168.10.70/26?",o:["192.168.10.0","192.168.10.64","192.168.10.70","192.168.10.127"],a:1,e:"/26 blocks are 64 wide: .0, .64, .128, .192. .70 falls in .64 to .127, so the network is .64 and broadcast is .127."},
{d:"sa",t:"Networking",q:"Which service automatically assigns IP addresses to hosts on a network?",o:["DNS","DHCP","ARP","SMTP"],a:1,e:"DHCP assigns IP configuration. DNS resolves names to IPs; ARP maps IP to MAC addresses on a LAN."},
{d:"sa",t:"Networking",q:"Which default port pair is correct?",o:["HTTPS 443, SSH 22","HTTPS 80, SSH 21","HTTP 443, SSH 23","HTTPS 8080, SSH 25"],a:0,e:"Common ports: HTTP 80, HTTPS 443, SSH 22, FTP 21, Telnet 23, SMTP 25, DNS 53."},
{d:"sa",t:"Networking",q:"Which HTTP status code means the request lacks valid authentication credentials?",o:["200","301","401","503"],a:2,e:"401 Unauthorized means authentication is required. 403 means authenticated but not allowed; 404 not found; 500/503 are server errors."},
{d:"sa",t:"Architecture & cloud",q:"A team deploys its code to a platform where the provider manages the OS, runtime and scaling; the team manages only the application and data. This is:",o:["IaaS","PaaS","SaaS","On-premises"],a:1,e:"PaaS (e.g. Heroku, App Engine). IaaS gives you VMs where you manage the OS; SaaS delivers a finished application (e.g. Gmail)."},
{d:"sa",t:"Architecture & cloud",q:"An SLA promises 99.99% availability per year. About how much downtime is allowed?",o:["About 8.8 hours","About 52.6 minutes","About 5.3 minutes","About 3.65 days"],a:1,e:"0.01% of 525,600 minutes is about 52.6 minutes. 99.9% allows about 8.8 hours; 99.999% about 5.3 minutes."},
{d:"sa",t:"Architecture & cloud",q:"A system has MTBF = 990 hours and MTTR = 10 hours. What is its availability?",o:["90%","98%","99%","99.9%"],a:2,e:"Availability = MTBF / (MTBF + MTTR) = 990 / 1000 = 99%."},
{d:"sa",t:"Architecture & cloud",q:"Adding more servers behind a load balancer to handle growing traffic is called:",o:["Vertical scaling (scale up)","Horizontal scaling (scale out)","Sharding the CPU","Failback"],a:1,e:"Scale out adds machines; scale up adds CPU/RAM to one machine. Horizontal scaling also improves availability."},
{d:"sa",t:"Architecture & cloud",q:"Which RAID level uses block striping with distributed parity and survives one disk failure?",o:["RAID 0","RAID 1","RAID 5","RAID 10"],a:2,e:"RAID 5 needs at least 3 disks. RAID 0 is striping with no redundancy; RAID 1 is mirroring; RAID 10 is mirrored stripes."},
{d:"sa",t:"Architecture & cloud",q:"How do containers (e.g. Docker) differ from virtual machines?",o:["Containers each include a full guest OS","Containers share the host OS kernel, making them lighter and faster to start","Containers require a Type 1 hypervisor","Containers cannot be networked"],a:1,e:"VMs virtualize hardware and each runs a guest OS. Containers isolate processes on a shared kernel."},
{d:"sa",t:"Architecture & cloud",q:"What is the main purpose of a Content Delivery Network (CDN)?",o:["Encrypt database records","Cache content on servers closer to users to reduce latency and origin load","Replace DNS","Assign IP addresses"],a:1,e:"CDN edge servers serve static (and some dynamic) content from locations near users."},
{d:"sa",t:"Architecture & cloud",q:"In a three-tier architecture, which tier contains business logic?",o:["Presentation tier","Application (logic) tier","Data tier","Network tier"],a:1,e:"Presentation (UI), application (business rules), data (database). Separating them improves scalability and maintainability."},
{d:"sa",t:"Cryptography",q:"Alice wants to send Bob a confidential message using asymmetric encryption. Which key does she use to encrypt it?",o:["Alice's private key","Alice's public key","Bob's public key","Bob's private key"],a:2,e:"Encrypt with the recipient's public key; only Bob's private key can decrypt it."},
{d:"sa",t:"Cryptography",q:"A digital signature is created with the sender's private key. Which properties does it provide?",o:["Confidentiality only","Authentication, integrity and non-repudiation","Availability and confidentiality","Compression and integrity"],a:1,e:"The signature (over a hash of the message) proves who sent it and that it was not altered. It does not encrypt the message."},
{d:"sa",t:"Cryptography",q:"Which is a symmetric encryption algorithm?",o:["RSA","AES","ECC","Diffie-Hellman"],a:1,e:"AES uses one shared key. RSA and ECC are asymmetric; Diffie-Hellman is a key-exchange method."},
{d:"sa",t:"Cryptography",q:"Why is a random salt added to each password before hashing?",o:["To make hashing reversible","To defeat precomputed rainbow-table attacks and make identical passwords hash differently","To speed up login","To encrypt the password"],a:1,e:"Salts make each hash unique. Use slow password hashes like bcrypt, scrypt or Argon2 as well."},
{d:"sa",t:"Cryptography",q:"In a PKI, what is the role of a Certificate Authority (CA)?",o:["Store users' private keys","Issue digital certificates that bind a public key to an identity","Encrypt all traffic","Assign domain names"],a:1,e:"The CA signs certificates so others can trust that a public key belongs to a given site or person."},
{d:"sa",t:"Cryptography",q:"HTTPS (TLS) typically uses asymmetric cryptography for what purpose?",o:["Encrypting all bulk data","Authenticating the server and establishing a shared session key","Compressing pages","Replacing DNS"],a:1,e:"Asymmetric crypto is slow, so it is used in the handshake; the bulk data is then encrypted with a fast symmetric session key."},
{d:"sa",t:"Web & app security",q:"Which vulnerability does this code contain?",c:`String q = "SELECT * FROM users WHERE id = '"
           + request.getParameter("id") + "'";
stmt.executeQuery(q);`,o:["Cross-site scripting","SQL injection","CSRF","Buffer overflow"],a:1,k:"code",e:"User input is concatenated into SQL. Input like ' OR '1'='1 changes the query. Fix with PreparedStatement (parameterized queries)."},
{d:"sa",t:"Web & app security",q:"What is the most effective primary defense against SQL injection?",o:["Hiding error messages","Parameterized queries (prepared statements)","Using HTTPS","Client-side JavaScript validation"],a:1,e:"Parameters keep data separate from SQL code. Least-privilege DB accounts and input validation are additional layers."},
{d:"sa",t:"Web & app security",q:"An attacker stores a <script> in a comment field, and it runs in other users' browsers when they view the page. This is:",o:["Stored XSS","SQL injection","CSRF","Clickjacking"],a:0,e:"Stored (persistent) XSS. Defend with context-aware output encoding, input validation and a Content Security Policy."},
{d:"sa",t:"Web & app security",q:"A malicious site makes a logged-in user's browser submit a money-transfer request to their bank. Which defense targets this attack?",o:["Anti-CSRF tokens and SameSite cookies","Password salting","RAID 1","Disabling DNS"],a:0,e:"This is Cross-Site Request Forgery. Unpredictable per-request tokens and SameSite cookies stop forged requests."},
{d:"sa",t:"Web & app security",q:"Logging in with a password plus a one-time code from your phone app combines which factors?",o:["Something you know + something you are","Something you know + something you have","Something you have + somewhere you are","Two of something you know"],a:1,e:"Password is knowledge; the phone/authenticator is possession. Biometrics are something you are."},
{d:"sa",t:"Security management",q:"Ransomware encrypts a hospital's records so staff cannot open them. Which part of the CIA triad is most directly affected?",o:["Confidentiality","Integrity","Availability","Non-repudiation"],a:2,e:"The data is not accessible when needed, which is an availability failure (as with DoS). Data exfiltration would hit confidentiality."},
{d:"sa",t:"Security management",q:"Granting users only the minimum permissions they need to do their job is the principle of:",o:["Separation of duties","Least privilege","Defense in depth","Security through obscurity"],a:1,e:"Least privilege limits damage from mistakes or compromised accounts."},
{d:"sa",t:"Security management",q:"Access rights are assigned to roles such as Cashier or Manager, and users get rights by being assigned roles. This model is:",o:["DAC","MAC","RBAC","ABAC"],a:2,e:"Role-Based Access Control. DAC lets owners grant access; MAC uses system-enforced labels; ABAC evaluates attributes."},
{d:"sa",t:"Security management",q:"What is the key difference between an IDS and an IPS?",o:["An IDS encrypts traffic","An IPS sits inline and can actively block malicious traffic; an IDS mainly detects and alerts","An IDS is hardware only","There is no difference"],a:1,e:"IDS is passive monitoring and alerting. IPS is inline prevention."},
{d:"sa",t:"Security management",q:"A company buys cyber-insurance to cover breach costs. Which risk treatment is this?",o:["Risk avoidance","Risk mitigation","Risk transfer","Risk acceptance"],a:2,e:"Transferring shifts the financial impact to a third party. Avoid = stop the activity; mitigate = reduce likelihood/impact; accept = live with it."},
{d:"sa",t:"Security management",q:"RPO (Recovery Point Objective) defines:",o:["The maximum acceptable downtime","The maximum acceptable data loss measured in time","The cost of recovery","The number of backup copies"],a:1,e:"RPO: how much data you can afford to lose (drives backup frequency). RTO: how quickly service must be restored."},
{d:"sa",t:"Security management",q:"An attacker emails staff pretending to be IT support and asks them to confirm their passwords on a fake page. This is:",o:["Phishing (social engineering)","Port scanning","SQL injection","Man-in-the-browser malware"],a:0,e:"Phishing exploits people, not code. Defenses include awareness training, MFA and email filtering."},

/* ================= IT BUSINESS ================= */
{d:"bz",t:"IT strategy",q:"In a SWOT analysis, which two elements are external to the organization?",o:["Strengths and Weaknesses","Opportunities and Threats","Strengths and Opportunities","Weaknesses and Threats"],a:1,e:"Strengths and weaknesses are internal; opportunities and threats come from the external environment."},
{d:"bz",t:"IT strategy",q:"Which is NOT one of Porter's Five Forces?",o:["Threat of new entrants","Bargaining power of suppliers","Threat of substitutes","Internal process efficiency"],a:3,e:"The five forces: new entrants, supplier power, buyer power, substitutes, and rivalry among existing competitors."},
{d:"bz",t:"IT strategy",q:"In the BCG matrix, a product with high market share in a low-growth market is a:",o:["Star","Cash cow","Question mark","Dog"],a:1,e:"Cash cows generate steady cash. Stars: high share, high growth. Question marks: low share, high growth. Dogs: low share, low growth."},
{d:"bz",t:"IT strategy",q:"Which system integrates core business processes such as finance, HR, inventory and procurement on a shared database?",o:["CRM","ERP","SCM only","CMS"],a:1,e:"ERP (e.g. SAP, Oracle) integrates enterprise processes. CRM manages customer relationships; SCM manages the supply chain."},
{d:"bz",t:"IT strategy",q:"A project costs 100,000 and produces a net gain of 150,000. Using ROI = (gain - cost) / cost, what is the ROI?",o:["33%","50%","150%","250%"],a:1,e:"(150,000 - 100,000) / 100,000 = 0.5, or 50%."},
{d:"bz",t:"IT strategy",q:"Moving from owned servers to a pay-as-you-go cloud service mainly shifts IT spending from:",o:["OpEx to CapEx","CapEx to OpEx","Fixed to sunk costs","Direct to indirect costs"],a:1,e:"Buying hardware is capital expenditure; subscription cloud fees are operating expenses."},
{d:"bz",t:"IT strategy",q:"Total Cost of Ownership (TCO) of a system includes:",o:["Only the purchase price","Purchase plus implementation, operation, maintenance, training and disposal costs","Only yearly license fees","Only hardware cost"],a:1,e:"TCO captures the full life-cycle cost, which is usually much larger than the purchase price."},
{d:"bz",t:"IT strategy",q:"A formal agreement between a service provider and customer that defines measurable service levels (uptime, response time, penalties) is a(n):",o:["NDA","SLA","RFP","MOU"],a:1,e:"Service Level Agreement. An RFP is a request for proposals; an NDA protects confidential information."},
{d:"bz",t:"IT strategy",q:"ITIL is best known as a framework for:",o:["IT service management","Programming language design","Database normalization","Network cabling standards"],a:0,e:"ITIL covers service strategy, design, transition, operation and continual improvement. COBIT focuses on IT governance and control."},
{d:"bz",t:"Emerging tech",q:"Which property best describes a blockchain?",o:["A central database controlled by one administrator","A distributed, append-only ledger whose records are hard to alter once confirmed","A faster replacement for TCP","A type of relational index"],a:1,e:"Blocks are linked by hashes and replicated across nodes; altering history requires redoing work across the network."},
{d:"bz",t:"Emerging tech",q:"Processing IoT sensor data on or near the device instead of sending everything to a distant cloud is called:",o:["Edge computing","Grid computing","Mainframe computing","Batch computing"],a:0,e:"Edge computing reduces latency and bandwidth use, which matters for real-time IoT applications."},
{d:"bz",t:"Emerging tech",q:"Training a model on emails labelled spam or not-spam is an example of:",o:["Unsupervised learning","Supervised learning","Reinforcement learning","Rule-based expert systems"],a:1,e:"Supervised learning uses labelled examples. Clustering without labels is unsupervised; learning from rewards is reinforcement learning."},
{d:"bz",t:"Emerging tech",q:"A model scores 99% on training data but 60% on new data. This most likely indicates:",o:["Underfitting","Overfitting","Data normalization","Perfect generalization"],a:1,e:"Overfitting: the model memorized training data. Remedies include more data, regularization, simpler models and cross-validation."},
{d:"bz",t:"Ethics & law",q:"Copyright protects:",o:["Ideas and algorithms themselves","The original expression of ideas, such as source code and documentation","Brand names and logos","Business processes only"],a:1,e:"Copyright covers expression. Patents protect inventions; trademarks protect brand identifiers; trade secrets protect confidential know-how."},
{d:"bz",t:"Ethics & law",q:"A company modifies GPL-licensed software and distributes the result to customers. What does the GPL require?",o:["Nothing, it is free software","The modified source must also be released under the GPL","The company must pay royalties","The company must rename the software"],a:1,e:"The GPL is a copyleft license: distributed derivative works must carry the same license and make source available. Permissive licenses (MIT, Apache) do not require this."},
{d:"bz",t:"Ethics & law",q:"Personal data collected for billing is later used for marketing without consent. Which data protection principle is violated?",o:["Purpose limitation","Data portability","Availability","Non-repudiation"],a:0,e:"Purpose limitation: data should only be used for the specified, legitimate purposes it was collected for. Data minimization and consent are related principles."},
{d:"bz",t:"Ethics & law",q:"An engineer finds a safety defect, but the manager says to ship anyway to meet the deadline. According to professional codes of ethics (e.g. ACM, IEEE), what comes first?",o:["The manager's instructions","The project deadline","Public safety and welfare","Avoiding conflict with the team"],a:2,e:"Professional codes put public health, safety and welfare first. The engineer should document and escalate the issue."},
{d:"bz",t:"Ethics & law",q:"A developer evaluating vendors owns shares in one of them and does not disclose it. This is a:",o:["Conflict of interest","Trade secret","Fair use","Service level breach"],a:0,e:"Personal interests that could bias professional judgment must be disclosed, and the person should usually step back from the decision."},
{d:"bz",t:"Project management",q:"The \"triple constraint\" (iron triangle) of project management consists of:",o:["Scope, time and cost","People, process and technology","Risk, quality and stakeholders","Plan, do and check"],a:0,e:"Changing one constraint affects the others; quality sits in the middle of the triangle."},
{d:"bz",t:"Project management",q:"What is a Work Breakdown Structure (WBS)?",o:["A Gantt chart of the schedule","A hierarchical decomposition of the project scope into deliverables and work packages","A list of team members","A risk register"],a:1,e:"The WBS breaks total scope into manageable work packages that can be estimated, scheduled and assigned."},
{d:"bz",t:"Project management",q:"A(3 days) starts the project. B(4) and C(2) both follow A. D(5) follows both B and C. What is the project duration and the float of C?",o:["10 days, float of C = 0","12 days, float of C = 2","14 days, float of C = 2","12 days, float of C = 0"],a:1,e:"Paths: A-B-D = 3 + 4 + 5 = 12 (critical) and A-C-D = 3 + 2 + 5 = 10. C can slip 12 - 10 = 2 days without delaying the project."},
{d:"bz",t:"Project management",q:"PV = 100, EV = 80, AC = 90. What is the project status?",o:["Ahead of schedule and under budget","Behind schedule and over budget","Behind schedule but under budget","On schedule and on budget"],a:1,e:"SV = EV - PV = -20 (behind). CV = EV - AC = -10 (over budget). SPI = 0.8, CPI = 0.89, both below 1."},
{d:"bz",t:"Project management",q:"In earned value management, the Cost Performance Index (CPI) is calculated as:",o:["EV / PV","EV / AC","AC / EV","PV / AC"],a:1,e:"CPI = EV / AC; SPI = EV / PV. Values below 1 are unfavorable."},
{d:"bz",t:"Project management",q:"Using PERT, an activity has optimistic 4, most likely 6 and pessimistic 14 days. What is the expected duration?",o:["6 days","7 days","8 days","8.5 days"],a:1,e:"(O + 4M + P) / 6 = (4 + 24 + 14) / 6 = 42 / 6 = 7 days."},
{d:"bz",t:"Project management",q:"In a RACI matrix, which role is held by exactly one person who ultimately answers for the task's outcome?",o:["Responsible","Accountable","Consulted","Informed"],a:1,e:"Many people can be Responsible (do the work), but only one is Accountable for each task."},
{d:"bz",t:"Project management",q:"Small, uncontrolled additions to project scope without adjusting time, cost or resources are known as:",o:["Gold plating","Scope creep","Crashing","Fast tracking"],a:1,e:"Scope creep is prevented with a formal change control process. Gold plating is the team adding extras nobody asked for."},
{d:"bz",t:"Project management",q:"To shorten a schedule, a manager adds extra resources to critical path activities at additional cost. This technique is:",o:["Fast tracking","Crashing","Resource leveling","Scope reduction"],a:1,e:"Crashing adds resources (cost) to shorten duration. Fast tracking overlaps activities that were planned in sequence (adds risk)."},
{d:"bz",t:"Project management",q:"\"Adding manpower to a late software project makes it later.\" This observation is known as:",o:["Moore's law","Brooks's law","Conway's law","Parkinson's law"],a:1,e:"Brooks's law: new people need ramp-up time and add communication overhead. Conway's law relates system design to org structure."},
{d:"bz",t:"Project management",q:"Which response to a negative risk reduces its probability or impact?",o:["Avoid","Transfer","Mitigate","Accept"],a:2,e:"Mitigation reduces likelihood or impact (e.g. extra testing, prototypes). Responses are tracked in the risk register."},
{d:"bz",t:"Technical communication",q:"What is the FIRST step when planning a technical document such as a user manual or report?",o:["Choose fonts and layout","Analyze the audience and purpose","Write the conclusion","Add screenshots"],a:1,e:"Audience and purpose decide the content, depth, terminology and structure of the document."},
{d:"bz",t:"Technical communication",q:"You are presenting a system upgrade proposal to non-technical executives. What should you emphasize?",o:["Detailed code architecture","Business impact: cost, benefits, risks and timeline","Every server configuration setting","Your preferred programming language"],a:1,e:"Executives decide on value and risk. Keep technical detail in an appendix for those who need it."},
{d:"bz",t:"Technical communication",q:"Well-written meeting minutes should, at minimum, record:",o:["Everything each person said word for word","Decisions made and action items with owners and due dates","Only the meeting time","The agenda only"],a:1,e:"Minutes exist to capture decisions and accountability so follow-up is clear."},
{d:"bz",t:"Technical communication",q:"In a long technical report for management, where should the executive summary go and what should it contain?",o:["At the end; a list of references","At the beginning; the key findings, conclusions and recommendations in brief","In the appendix; raw data","After the methodology; detailed formulas"],a:1,e:"Busy readers may read only the executive summary, so it comes first and stands on its own."},
{d:"bz",t:"Technical communication",q:"Which writing style is generally preferred for technical instructions?",o:["Passive, impersonal sentences","Short, active-voice, imperative steps in numbered order","Long paragraphs with background first","Jargon-heavy wording to sound precise"],a:1,e:"E.g. \"Click Save.\" rather than \"The Save button should be clicked.\" Numbered steps match the order of the task."},

/* ================= DESCRIPTIVE (self-graded) ================= */
{d:"sw",t:"SDLC & methods",k:"desc",q:"Compare the Waterfall and Agile (e.g. Scrum) approaches. Give one situation where each is the better choice.",m:"Waterfall: sequential phases (requirements, design, implementation, testing, deployment) with sign-off between them; heavy upfront documentation; change is expensive late. Best for stable, well-defined requirements, fixed-price contracts or regulated projects (e.g. a payroll module defined by law).\n\nAgile/Scrum: short iterations (sprints) that deliver working increments; backlog reprioritized each sprint; close customer collaboration; embraces change. Best when requirements are unclear or changing and early feedback matters (e.g. a new mobile app for a startup).\n\nKey contrasts to mention: predictability vs adaptability, documentation vs working software, testing at the end vs testing every iteration."},
{d:"sw",t:"Testing",k:"desc",q:"Explain the difference between black-box and white-box testing. Name one technique for each and show how you would apply it.",m:"Black-box: tests behavior from the specification without looking at code. Example: equivalence partitioning for an age field 18-60: valid class (e.g. 30), invalid below (10), invalid above (70); plus boundary values 17, 18, 60, 61.\n\nWhite-box: tests based on internal structure of the code. Example: branch/decision coverage: design tests so each if/else outcome executes at least once; or statement and path coverage; cyclomatic complexity gives the number of independent paths.\n\nBlack-box finds missing or wrong functionality; white-box finds untested logic and dead code. Both are needed."},
{d:"sw",t:"UML & design",k:"desc",q:"Define coupling and cohesion. Why should a design aim for low coupling and high cohesion? Give an example of improving a design.",m:"Coupling: degree of interdependence between modules. Cohesion: how strongly the elements within one module belong to a single purpose.\n\nLow coupling means a change in one module rarely forces changes in others, modules can be tested and reused independently. High cohesion means modules are easier to understand, maintain and name.\n\nExample: a UserManager class that handles login, sends emails and writes reports has low cohesion. Split into AuthService, EmailService and ReportService (high cohesion), and have them communicate through interfaces / dependency injection rather than direct access to each other's internals (low coupling)."},
{d:"db",t:"Normalization",k:"desc",q:"Normalize to 3NF: Order(OrderID, OrderDate, CustomerID, CustomerName, ProductID, ProductName, UnitPrice, Qty). Key = (OrderID, ProductID). State the dependencies you used.",m:"Dependencies: OrderID -> OrderDate, CustomerID; CustomerID -> CustomerName; ProductID -> ProductName, UnitPrice; (OrderID, ProductID) -> Qty.\n\n2NF (remove partial dependencies): split out Order(OrderID, OrderDate, CustomerID, CustomerName) and Product(ProductID, ProductName, UnitPrice), leaving OrderLine(OrderID, ProductID, Qty).\n\n3NF (remove transitive CustomerID -> CustomerName): Customer(CustomerID, CustomerName); Order(OrderID, OrderDate, CustomerID FK).\n\nResult: Customer(CustomerID PK, CustomerName); Orders(OrderID PK, OrderDate, CustomerID FK); Product(ProductID PK, ProductName, UnitPrice); OrderLine(OrderID FK, ProductID FK, Qty) with PK (OrderID, ProductID).\n\nNote: if the price paid can change over time, store the sold price in OrderLine too."},
{d:"db",t:"SQL",k:"desc",q:"Tables: employee(emp_id, name, dept_id, salary) and department(dept_id, dept_name). Write SQL that lists each department name with its number of employees and average salary, only for departments with at least 3 employees, highest average first.",m:"SELECT d.dept_name,\n       COUNT(e.emp_id) AS emp_count,\n       AVG(e.salary)   AS avg_salary\nFROM department d\nJOIN employee e ON e.dept_id = d.dept_id\nGROUP BY d.dept_id, d.dept_name\nHAVING COUNT(e.emp_id) >= 3\nORDER BY avg_salary DESC;\n\nCheck: join on the key, group by the non-aggregated columns, aggregate condition in HAVING (not WHERE), ORDER BY can use the alias."},
{d:"db",t:"Transactions",k:"desc",q:"Explain the four ACID properties using a bank transfer of 1,000 from account A to account B.",m:"Atomicity: debit A and credit B both happen or neither does; a crash after the debit triggers a rollback.\nConsistency: the transaction moves the DB from one valid state to another; total money is unchanged and constraints (e.g. balance >= 0) hold.\nIsolation: concurrent transactions do not see each other's partial work; another query never sees A debited but B not yet credited (controlled by locking/isolation levels).\nDurability: once committed, the transfer survives crashes or power loss (write-ahead log, persistent storage)."},
{d:"sa",t:"Cryptography",k:"desc",q:"Explain how HTTPS/TLS uses both asymmetric and symmetric cryptography, and why both are needed.",m:"1. Client connects; the server sends its certificate (its public key signed by a trusted CA).\n2. The client verifies the certificate chain and domain name, authenticating the server.\n3. Asymmetric cryptography (e.g. ECDHE key exchange, signed by the server's key) is used to agree on a shared secret.\n4. Both sides derive symmetric session keys (e.g. AES-GCM) and encrypt all application data with them, with integrity protection.\n\nWhy both: asymmetric solves key distribution and authentication but is slow; symmetric is fast for bulk data but needs a shared key. TLS combines them (hybrid encryption)."},
{d:"sa",t:"Web & app security",k:"desc",q:"Describe how a SQL injection attack works, with an example input, and give at least two defenses.",m:"How: the application builds a SQL statement by concatenating user input, so input can change the query's structure.\nExample: SELECT * FROM users WHERE name = '<input>' AND pw = '<input>'. Entering  ' OR '1'='1' --  as the name makes the condition always true and comments out the password check, bypassing login.\n\nDefenses:\n1. Parameterized queries / prepared statements (primary defense).\n2. Input validation (allow-lists for format, length, type).\n3. Least-privilege database accounts so injected queries cannot drop tables or read everything.\n4. Stored procedures with parameters, ORM frameworks, generic error messages, and a WAF as an extra layer."},
{d:"sa",t:"Architecture & cloud",k:"desc",q:"A web app on a single server keeps going down during enrollment week. Propose an architecture to improve availability and scalability.",m:"Points to include:\n- Remove single points of failure: run multiple stateless app servers behind a load balancer with health checks (horizontal scaling, auto-scaling in the cloud).\n- Keep session state out of the app servers (shared cache such as Redis, or tokens).\n- Database: primary with replicas (read replicas, automatic failover); use connection pooling; cache frequent queries.\n- Serve static content through a CDN.\n- Deploy across multiple availability zones; set up monitoring and alerts.\n- Load test before peak periods; define RTO/RPO and back up regularly.\n- Optionally use a queue for heavy background jobs (e.g. report generation)."},
{d:"bz",t:"Project management",k:"desc",q:"At the end of month 4: PV = 400,000, EV = 320,000, AC = 360,000. Compute SV, CV, SPI and CPI, interpret them, and suggest one corrective action.",m:"SV = EV - PV = 320,000 - 400,000 = -80,000 (behind schedule)\nCV = EV - AC = 320,000 - 360,000 = -40,000 (over budget)\nSPI = EV / PV = 0.80 (only 80% of planned work done)\nCPI = EV / AC = 0.89 (getting 0.89 of value per 1 spent)\n\nInterpretation: the project is behind schedule and over budget. If BAC were known, EAC = BAC / CPI estimates final cost.\n\nCorrective actions: re-baseline with the sponsor, fast-track or crash critical-path tasks (weighing cost), reduce or defer low-priority scope via change control, investigate root causes of cost overrun."},
{d:"bz",t:"Ethics & law",k:"desc",q:"A company plans to use an AI tool to screen job applicants. Identify three ethical or legal issues and a mitigation for each.",m:"1. Bias and discrimination: model trained on historical hiring data may disadvantage groups. Mitigation: audit training data and outcomes for fairness across groups, remove proxy features, regular bias testing.\n2. Transparency and explainability: applicants cannot know why they were rejected. Mitigation: explainable criteria, inform applicants that AI is used, provide a way to request human review.\n3. Privacy and data protection: collection of personal data beyond need. Mitigation: data minimization, consent, purpose limitation, secure storage and retention limits per data privacy law.\n4. Accountability: keep a human in the loop for final decisions and assign clear responsibility."},
{d:"bz",t:"Technical communication",k:"desc",q:"Outline the structure of a one-page project status report for executives. What should each part contain?",m:"1. Header: project name, reporting period, overall status (e.g. green/amber/red).\n2. Summary: 2 to 3 sentences on where the project stands and the key message.\n3. Progress: milestones completed this period vs planned.\n4. Schedule and budget: SPI/CPI or plan vs actual figures.\n5. Risks and issues: top items with impact, owner and response.\n6. Decisions or support needed from executives.\n7. Next steps: key activities for the next period with dates.\n\nStyle: concise, business impact first, no unexplained jargon, visuals for status where helpful."}
];
